'use strict';

// MODULES //

var join = require( 'path' ).join;
var isArray = require( '@stdlib/assert/is-array' );
var bench = require( '@stdlib/bench' );
var format = require( '@stdlib/string/format' );
var extract = require( './../lib' );
var pkg = require( './../package.json' ).name;


// VARIABLES //

var FIXTURES_DIR = join( __dirname, '..', 'test', 'fixtures' );
var SRC_FILE = join( FIXTURES_DIR, 'src', 'test_edge_cases.c' );
var MD_FILE = join( FIXTURES_DIR, '..', '..', '..', '..', '..', '..', 'math', 'base', 'special', 'abs', 'README.md' );


// MAIN //

bench( format( '%s::src', pkg ), function benchmark( b ) {
	var out;
	var i;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = extract( SRC_FILE, 'src' );
		if ( typeof out !== 'object' ) {
			b.fail( 'should return an array' );
		}
	}
	b.toc();
	if ( !isArray( out ) ) {
		b.fail( 'should return an array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::markdown', pkg ), function benchmark( b ) {
	var out;
	var i;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = extract( MD_FILE, 'markdown' );
		if ( typeof out !== 'object' ) {
			b.fail( 'should return an array' );
		}
	}
	b.toc();
	if ( !isArray( out ) ) {
		b.fail( 'should return an array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
